use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,OriginalTurnFailure,StepContext,default_now_us,OriginalConstructionDemand,close_original_retained_step};
use crate::admission::{admit_original_construction_settled,tests::admitted_decoder};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand};
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:128};
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(20751),Generation(52),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:128},default_now_us,u64::MAX,1<<30)}
fn event<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn construct_grant(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->RetainedCloneGrant{let refresh=event(caller,decoder,TURN,|cx|Ok(semio_framework_job::original_return_refresh_quote(cx)?));RetainedCloneGrant{maximum_items:16+refresh.copied_items,maximum_copy_bytes:TURN.maximum_copy_bytes+refresh.copied_bytes,..TURN}}
type Admission=semio_framework_job::OriginalConstructionAdmission;
fn built<O>(cx:&mut StepContext<'_>,adm:&mut Admission,out:&mut Option<O>,d:RetirementDemand,f:impl FnOnce()->Result<(O,RetainedCloneProgress),semio_framework_value::ValueError>)->Result<bool,OriginalTurnFailure>{admit_original_construction_settled(cx,adm,out,original(d),1,|_,actual|{let result=f();if let Ok((_,progress))=&result{if progress.retained_capacity_bytes!=0&&actual.is_none(){*actual=Some(progress.retained_capacity_bytes)}}semio_framework_value::RetainedWorkOutcome{work:u128::from(result.is_ok()),result}})}
fn close_demand(input:&RetainedToolWireInput)->RetirementDemand{RetirementDemand{copy_bytes:input.next_close_copy_byte_demand().unwrap(),release_bytes:input.next_close_release_byte_demand().unwrap(),depth:input.next_close_depth_demand().unwrap(),..Default::default()}}
fn denied(d:RetirementDemand,axis:usize)->Option<RetainedCloneGrant>{let mut g=TURN;match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>return None}Some(g)}
#[doc(hidden)]
pub fn original_command_wire_backing_is_admitted_before_pages_and_denied_close_preserves_the_same_owner(){
 let law:semio_framework_value::serde_json::Value=semio_framework_value::serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){let bytes=row["bytes"].as_u64().unwrap()as usize;let pages=row["pages"].as_u64().unwrap()as usize;
  for cut in law["cancelAfterPages"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain([None]){
   let mut caller=caller();let mut decoder=admitted_decoder(&mut caller);let construct=construct_grant(&mut caller,&mut decoder);let mut input=None;let d=RetainedToolWireInput::original_birth_demands(bytes,bytes).unwrap();
   for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(event(&mut caller,&mut decoder,g,|_|Ok(RetainedToolWireInput::admit_original(bytes,bytes,g)?)).is_none());assert!(input.is_none());assert_eq!(caller.receipt(),Default::default());}
   {let mut adm=Admission::default();for _ in 0..64{if event(&mut caller,&mut decoder,construct,|cx|built(cx,&mut adm,&mut input,d,||Ok(RetainedToolWireInput::admit_original(bytes,bytes,TURN)?.unwrap()))){break}}}
   let input=input.as_mut().unwrap();assert_eq!(input.pages.capacity(),pages);let pointer=input.pages.as_ptr();
   for page in 0..pages{if cut==Some(page){break}let offset=page*TOOL_WIRE_PAGE_BYTES;let count=(bytes-offset).min(TOOL_WIRE_PAGE_BYTES);let d=RetirementDemand{copy_bytes:3*size_of::<ToolWirePage>()+count+3*size_of::<usize>(),depth:1,..Default::default()};{let mut adm=Admission::default();let mut done=None;for _ in 0..64{if event(&mut caller,&mut decoder,construct,|cx|built(cx,&mut adm,&mut done,d,||{let mut scratch=[0;TOOL_WIRE_PAGE_BYTES];for(index,byte)in scratch[..count].iter_mut().enumerate(){*byte=((offset+index)*37+19)as u8}input.admit_page(ToolWirePage::try_copy_from(&scratch[..count]).unwrap()).unwrap();Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})){break}}}assert_eq!(input.pages.as_ptr(),pointer);}
   if cut.is_none(){{let d=RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()};let mut adm=Admission::default();let mut done=None;for _ in 0..64{if event(&mut caller,&mut decoder,construct,|cx|built(cx,&mut adm,&mut done,d,||{input.seal().unwrap();Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})){break}}}assert_eq!(input.page_count(),pages);for page in 0..pages{for(index,byte)in input.page(page).unwrap().iter().enumerate(){assert_eq!(*byte,((page*TOOL_WIRE_PAGE_BYTES+index)*37+19)as u8);}}}else{caller.cancel().cancel_now()}
   let d=close_demand(input);let state=(input.closing,input.sealed,input.admitted_bytes,input.pages.as_ptr(),input.pages.len(),input.pages.capacity());
   for axis in 0..5{let Some(g)=denied(d,axis)else{continue};let served=event(&mut caller,&mut decoder,g,|cx|{let served=semio_framework_job::original_return_refresh_quote(cx)?;cx.with_original_retirement(|cx|{let p=input.close_step(g)?.progress();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);Ok(())})?;Ok(served)});assert_eq!(caller.receipt(),if served.fits(g)&&g.maximum_depth>0{served}else{Default::default()});assert_eq!((input.closing,input.sealed,input.admitted_bytes,input.pages.as_ptr(),input.pages.len(),input.pages.capacity()),state);assert_eq!(close_demand(input),d);}
   event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|grant|match input.close_step(grant){Ok(step)=>semio_framework_value::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(step.progress())),work:1},Err(error)=>semio_framework_value::RetainedWorkOutcome{result:Err(semio_framework_job::OriginalTurnPrimary::from(error)),work:0}})?;Ok(())}));assert!(input.terminal_is_empty());
   crate::admission::tests::close(&mut caller,&mut decoder);caller.retire(TURN);
  }
 }
}

#[cfg(test)]
#[test]
fn original_command_wire_law(){original_command_wire_backing_is_admitted_before_pages_and_denied_close_preserves_the_same_owner()}

#[test]
fn original_registration_admission_keeps_owned_sources_on_denial_and_returns_the_exact_factory(){
 let law:semio_framework_value::serde_json::Value=semio_framework_value::serde_json::from_str(include_str!("📋️admission.json")).unwrap();let bus=ActionBus::new();let contract=ToolExecutionContract::resumable(1024,32,64,1024,1000,1,1);let mut inner=bus.inner.lock().unwrap();inner.original_entries.push(OriginalWireRegistration{key:ToolFactoryKey::new(law["controller"].as_str().unwrap(),law["tool"].as_str().unwrap()),schema:law["schema"].as_str().unwrap().into(),factory_type_id:std::any::TypeId::of::<u64>(),factory_type_name:std::any::type_name::<u64>(),contract});drop(inner);
 let mut caller=caller();let mut decoder=admitted_decoder(&mut caller);let mut key=Some(ToolFactoryKey::new("controller","import-media"));let mut schema=Some("schema".to_owned());let mut cursor=None;let mut output=None;let mut construction=semio_framework_job::OriginalConstructionAdmission::default();let mut denied=TURN;denied.maximum_items=0;
 event(&mut caller,&mut decoder,denied,|cx|{assert_eq!(OriginalWireAdmission::admit(&mut key,&mut schema,8,cx,&mut construction,&mut cursor)?,semio_framework_job::OriginalConstructionStatus::Pending);Ok(())});assert!(key.is_some()&&schema.is_some()&&cursor.is_none());
 for _ in 0..100{if event(&mut caller,&mut decoder,TURN,|cx|OriginalWireAdmission::admit(&mut key,&mut schema,8,cx,&mut construction,&mut cursor))==semio_framework_job::OriginalConstructionStatus::Ready{break}}assert!(key.is_none()&&schema.is_none());event(&mut caller,&mut decoder,TURN,|cx|construction.reset_step(cx));
 for _ in 0..100{if event(&mut caller,&mut decoder,TURN,|cx|cursor.as_mut().unwrap().advance(&bus,cx,&mut construction,&mut output)){break}}event(&mut caller,&mut decoder,TURN,|cx|construction.reset_step(cx));let result=output.as_ref().expect("exact admitted factory");let oracle=semio_framework_value::serde_json::json!({"controller":result.key.controller_id.as_str(),"tool":result.key.tool_id.as_str(),"schema":result.schema_id.as_str(),"rawBytes":8,"factory":result.factory_type_name});assert_eq!(oracle,law);assert_eq!(result.factory_type_id,std::any::TypeId::of::<u64>());assert_eq!(result.contract,contract);
 for _ in 0..100{if cursor.as_ref().unwrap().terminal_is_empty(){break}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|cursor.as_mut().unwrap().close_step(&bus,cx)));}assert!(cursor.as_ref().unwrap().terminal_is_empty());drop(cursor.take());
 let mut retirement=semio_framework_value::retained_clone::RetainedCloneClose::default();for _ in 0..1000{if output.is_none()&&retirement.is_empty(){break}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=retirement.next_owner_demands::<ToolWireAdmission>(output.is_some(),&None,32768)?;semio_framework_job::close_original_effect_step(cx,d,|effect|if retirement.is_empty(){let turn=retirement.begin_granted(&mut output,effect);semio_framework_value::RetirementPollExit::settle(effect,turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Complete(Default::default()))).map_err(Into::into))}else{retirement.step_granted(effect.grant().maximum_copy_bytes,effect)})?;Ok(())}));}assert!(output.is_none()&&retirement.is_empty());crate::admission::tests::close(&mut caller,&mut decoder);caller.retire(TURN);
}

#[test]
fn original_registration_cancellation_retires_the_partially_compared_sources(){
 let bus=ActionBus::new();let long="x".repeat(8193);let contract=ToolExecutionContract::resumable(1024,32,64,1024,1000,1,1);bus.inner.lock().unwrap().original_entries.push(OriginalWireRegistration{key:ToolFactoryKey::new(long.clone(),"import-media"),schema:"schema".into(),factory_type_id:std::any::TypeId::of::<u64>(),factory_type_name:std::any::type_name::<u64>(),contract});
 let mut caller=caller();let mut decoder=admitted_decoder(&mut caller);let mut key=Some(ToolFactoryKey::new(long,"import-media"));let mut schema=Some("schema".to_owned());let mut cursor=None;let mut output=None;let mut construction=semio_framework_job::OriginalConstructionAdmission::default();for _ in 0..100{if event(&mut caller,&mut decoder,TURN,|cx|OriginalWireAdmission::admit(&mut key,&mut schema,8,cx,&mut construction,&mut cursor))==semio_framework_job::OriginalConstructionStatus::Ready{break}}event(&mut caller,&mut decoder,TURN,|cx|construction.reset_step(cx));for _ in 0..2{event(&mut caller,&mut decoder,TURN,|cx|cursor.as_mut().unwrap().advance(&bus,cx,&mut construction,&mut output));}let mut page=TURN;page.maximum_copy_bytes=3*size_of::<usize>()+17;event(&mut caller,&mut decoder,page,|cx|cursor.as_mut().unwrap().advance(&bus,cx,&mut construction,&mut output));assert!(output.is_none());assert!(caller.receipt().copied_bytes>3*size_of::<usize>());caller.cancel().cancel_now();
 for _ in 0..10000{if cursor.as_ref().unwrap().terminal_is_empty(){break}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|cursor.as_mut().unwrap().close_step(&bus,cx)));}assert!(cursor.as_ref().unwrap().terminal_is_empty());drop(cursor.take());assert!(output.is_none());crate::admission::tests::close(&mut caller,&mut decoder);caller.retire(TURN);
}

#[test]
fn original_registration_of_an_unregistered_tool_is_a_typed_invalid_value_refusal(){
 let bus=ActionBus::new();
 let mut caller=caller();let mut decoder=admitted_decoder(&mut caller);let mut key=Some(ToolFactoryKey::new("controller","import-media"));let mut schema=Some("schema".to_owned());let mut cursor=None;let mut output=None;let mut construction=semio_framework_job::OriginalConstructionAdmission::default();
 for _ in 0..100{if event(&mut caller,&mut decoder,TURN,|cx|OriginalWireAdmission::admit(&mut key,&mut schema,8,cx,&mut construction,&mut cursor))==semio_framework_job::OriginalConstructionStatus::Ready{break}}event(&mut caller,&mut decoder,TURN,|cx|construction.reset_step(cx));
 let mut refusal=None;for _ in 0..10{if let Err(failure)=caller.turn_with_decoder(TURN,&mut decoder,|cx|cursor.as_mut().unwrap().advance(&bus,cx,&mut construction,&mut output)){refusal=Some(failure);break}}
 let failure=refusal.expect("an unregistered tool must be refused");assert!(matches!(&failure.primary,semio_framework_job::OriginalTurnPrimary::Value(error) if error.kind==semio_framework_value::ValueRefusalKind::InvalidValue),"{failure:?}");
 for _ in 0..10000{if cursor.as_ref().unwrap().terminal_is_empty(){break}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|cursor.as_mut().unwrap().close_step(&bus,cx)));}assert!(cursor.as_ref().unwrap().terminal_is_empty());drop(cursor.take());assert!(output.is_none());crate::admission::tests::close(&mut caller,&mut decoder);caller.retire(TURN);
}
